// YouTube helpers — accept full URL (youtu.be/watch?v=) or bare 11-char ID
const ytId = (url) => {
  if (!url) return null
  const m = url.match(/(?:youtu\.be\/|[?&]v=|embed\/|shorts\/)([A-Za-z0-9_-]{11})/)
  return m ? m[1] : url.trim()
}
const ytThumb = (url) => ytId(url)
  ? `https://i.ytimg.com/vi_webp/${ytId(url)}/sddefault.webp`
  : 'https://i.ytimg.com/vi_webp/djMI5NyvFX0/sddefault.webp'
const ytEmbed = (url) => ytId(url)
  ? `https://www.youtube.com/embed/${ytId(url)}?iv_load_policy=3&rel=0&modestbranding=1&playsinline=1&autoplay=0`
  : 'https://www.youtube.com/embed/djMI5NyvFX0?iv_load_policy=3&rel=0&modestbranding=1&playsinline=1&autoplay=0'

